1	import * as Cloudflare from "@alchemy.run/cloudflare";
2	import { SqliteClient } from "@effect/sql-sqlite-do";
3	import { organizationActions } from "./organization/Actions.ts";
4	import { organizationDirectory } from "./organization/Directory.ts";
5	import { makeEmailOutbox } from "./organization/EmailOutbox.ts";
6	import { organizationEmailVisibility } from "./organization/EmailVisibility.ts";
7	import { organizationSubmissions } from "./organization/Submissions.ts";
8	import { organizationNotes } from "./organization/Notes.ts";
9	import { organizationRoundViews } from "./organization/RoundViews.ts";
10	import { organizationResults } from "./organization/Results.ts";
11	import { organizationSends } from "./organization/Sends.ts";
12	import {
13	  decidePulse,
14	  decideTestSend,
15	  type PulseCommand,
16	  type PulseCommandResult,
17	  PulseId,
18	  pulsesView,
19	  pulseView,
20	  type TestSendResult,
21	  testInvitationLifetimeMs,
22	  testSendsPerHour,
23	  defaultSendPolicy,
24	  type DirectoryState,
25	  emailLocaleOf,
26	  makeSendStore,
27	  PersonId,
28	  SendId,
29	  TeamId,
30	  type TransactionalEmail,
31	  calculateReminders,
32	  calculateResultsReadyDeliveryTime,
33	  calculateRoundInstants,
34	  deriveInvitationToken,
35	  deriveTestInvitationToken,
36	  hashToken,
37	  importInvitationTokenKey,
38	  type InvitationTokenRef,
39	  type StoredEmail,
40	  nextEightWeeksCadenceDates,
41	  nextRoundSlot,
42	  RoundId,
43	  JobId,
44	  type RoundRecord,
45	  type RoundCommand,
46	  type RoundCommandResult,
47	  authorizeRoundAction,
48	  roundCommandRejection,
49	  type FrozenRoundMember,
50	  type PulseRecord,
51	  type PulseState,
52	  calculateRoundResult,
53	  enforceEffectiveNOnResult,
54	  AiClient,
55	  buildThemesInput,
56	  runThemesAttempt,
57	  shouldRequestThemes,
58	  delayedRoundResult,
59	  nextRetryAt,
60	  Policy,
61	} from "@surveybeat/domain";
62	import * as Clock from "effect/Clock";
63	import * as Config from "effect/Config";
64	import * as Effect from "effect/Effect";
65	import * as Layer from "effect/Layer";
66	import * as Option from "effect/Option";
67	import * as Redacted from "effect/Redacted";
68	import * as Reactivity from "effect/reactivity/Reactivity";
69	import * as Schema from "effect/Schema";
70	import * as Scope from "effect/Scope";
71	import { makeOpenRouterAiClient } from "./ai/OpenRouterAiClient.ts";
72	import { EmailQueue } from "./Email.ts";
73	import { makeSqlActions } from "./SqlActions.ts";
74	import { makeSqlNotes } from "./SqlNotes.ts";
75	import { makeSqlDirectory } from "./SqlDirectory.ts";
76	import { makeSqlPulses } from "./SqlPulses.ts";
77	import { makeSqlRounds, secureRandomBytes } from "./SqlRounds.ts";
78	import { makeSqlSendRepository } from "./SqlSendRepository.ts";
79	
80	const migrationsDirectory = "packages/cloudflare/migrations";
81	
82	const THEMES_LEASE_MS = 10 * 60_000;
83	
84	const fallbackAppOrigin = "https://app.invalid";
85	
86	const randomId = (): string =>
87	  Array.from(crypto.getRandomValues(new Uint8Array(16)), (byte) => byte.toString(16).padStart(2, "0")).join(
88	    "",
89	  );
90	
91	const TestSendCount = Schema.Struct({ n: Schema.Int });
92	
93	const AttemptsPayload = Schema.Struct({ attempts: Schema.Int });
94	const parseAttempts = (payload: string | null): number => {
95	  if (payload === null) return 0;
96	  try {
97	    const p: unknown = JSON.parse(payload);
98	    const decoded = Schema.decodeUnknownOption(AttemptsPayload)(p);
99	    return Option.match(decoded, {
100	      onNone: () => 0,
101	      onSome: (val) => val.attempts,
102	    });
103	  } catch {
104	    return 0;
105	  }
106	};
107	
108	const organizationObject = Effect.gen(function* () {
109	  const migrations = yield* Cloudflare.SqlMigrations(migrationsDirectory);
110	  const emailQueue = yield* Cloudflare.Queues.WriteQueue(yield* EmailQueue);
111	
112	  // @effect-diagnostics-next-line returnEffectInGen:off -- the object setup must be returned, not yielded: flattening it would run the setup when the outer phase runs, not once per activation.
113	  return Effect.gen(function* () {
114	    const state = yield* Cloudflare.DurableObjectState;
115	
116	    const appOrigin = yield* Config.String("APP_ORIGIN").pipe(
117	      Config.withDefault(fallbackAppOrigin),
118	      Effect.orDie,
119	    );
120	
121	    const invitationKey = yield* Config.Redacted("INVITATION_TOKEN_KEY").pipe(
122	      Effect.flatMap((secret) => Effect.promise(() => importInvitationTokenKey(Redacted.value(secret)))),
123	      Effect.orDie,
124	    );
125	    const tokenOf = (ref: InvitationTokenRef) =>
126	      Effect.promise(() => deriveInvitationToken(invitationKey, ref));
127	
128	    const aiKey = yield* Config.Redacted("OPENROUTER_API_KEY").pipe(
129	      Config.withDefault(Redacted.make("")),
130	      Effect.orDie,
131	    );
132	    const ai = makeOpenRouterAiClient(aiKey);
133	
134	    const scope = yield* Scope.make();
135	    const sql = yield* SqliteClient.make({ storage: state.raw.storage }).pipe(
136	      Effect.provideService(Scope.Scope, scope),
137	      Effect.provide(Reactivity.layer),
138	    );
139	
140	    yield* migrations.apply().pipe(Effect.orDie);
141	
142	    const rounds = makeSqlRounds(sql, secureRandomBytes);
143	    const outbox = makeEmailOutbox(sql, emailQueue);
144	
145	    const repairAlarm = () =>
146	      Effect.gen(function* () {
147	        const nextJob = yield* rounds.getEarliestPendingJobDueAt();
148	        const now = yield* Clock.currentTimeMillis;
149	        const sendsWaiting = yield* outbox.isWaiting;
150	        const earliest = sendsWaiting ? Math.min(now, nextJob ?? now) : nextJob;
151	        if (earliest !== null) {
152	          const currentAlarm = yield* Effect.promise(() => state.raw.storage.getAlarm());
153	          if (currentAlarm !== earliest) {
154	            yield* Effect.promise(() => state.raw.storage.setAlarm(earliest));
155	          }
156	        } else {
157	          yield* Effect.promise(() => state.raw.storage.deleteAlarm());
158	        }
159	      }).pipe(Effect.orDie);
160	
161	    const sends = outbox.recording(
162	      makeSendStore(makeSqlSendRepository(sql), defaultSendPolicy),
163	      Effect.suspend(() => repairAlarm()),
164	    );
165	    const directory = makeSqlDirectory(sql, sends);
166	    const pulses = makeSqlPulses(sql);
167	    const actions = makeSqlActions(sql);
168	    const notes = makeSqlNotes(sql);
169	    const both = Effect.all([directory.load, pulses.load]);
170	
171	    const activeMembersWithTimeZones = (dirState: DirectoryState, teamId: TeamId, teamTimeZone: string) =>
172	      Effect.gen(function* () {
173	        const activeMembers = dirState.memberships.filter(
174	          (m) => m.teamId === teamId && m.endedAt === null && (m.role === "lead" || m.role === "member"),
175	        );
176	        const memberTimeZones = yield* Effect.forEach(activeMembers, (m) =>
177	          rounds.getPersonTimeZone(m.personId).pipe(Effect.map((tz) => tz ?? teamTimeZone)),
178	        );
179	        return { activeMembers, memberTimeZones };
180	      });
181	
182	    const scheduleNextRound = (pulseId: PulseId, teamId: TeamId, now: number) =>
183	      Effect.gen(function* () {
184	        const paused = yield* rounds.isPulsePaused(pulseId);
185	        if (paused) return;
186	
187	        const existingScheduled = yield* rounds.findScheduledRound(pulseId);
188	        if (existingScheduled !== null) return;
189	
190	        const [dirState, pulseState] = yield* both;
191	        const pulse = pulseState.pulses.find((p) => p.id === pulseId);
192	        if (pulse === undefined) return;
193	        const team = dirState.teams.find((t) => t.id === teamId);
194	        if (team === undefined) return;
195	
196	        const { memberTimeZones } = yield* activeMembersWithTimeZones(dirState, teamId, team.timeZone);
197	        const { plannedOpenDate, instants } = nextRoundSlot({
198	          now,
199	          weekday: pulse.settings.cadence.day,
200	          sendTime: pulse.settings.cadence.time,
201	          teamTimeZone: team.timeZone,
202	          memberTimeZones,
203	          answerWindowDays: pulse.settings.answerWindowDays,
204	          unavailableDates: yield* rounds.getUnavailableRoundDates(pulseId, null),
205	        });
206	
207	        const roundId = RoundId.make(randomId());
208	        const round: RoundRecord = {
209	          id: roundId,
210	          pulseId,
211	          teamId,
212	          status: "scheduled",
213	          plannedOpenDate,
214	          plannedOpenAt: instants.openInstant,
215	          openedAt: null,
216	          plannedCloseAt: instants.closeInstant,
217	          closedAt: null,
218	          reviewEndsAt: null,
219	          effectiveMinimumGroupSize: null,
220	          pulseName: pulse.settings.name,
221	          answerWindowDays: pulse.settings.answerWindowDays,
222	          reminders: pulse.settings.reminders,
223	          anonymityMode: pulse.settings.anonymityMode,
224	          distribution: pulse.settings.distribution,
225	          createdAt: now,
226	          updatedAt: now,
227	        };
228	
229	        yield* rounds.insertRound(round);
230	        yield* rounds.insertJob({
231	          id: JobId.make(randomId()),
232	          roundId,
233	          type: "open",
234	          dueAt: instants.openInstant,
235	          status: "pending",
236	          payload: null,
237	          createdAt: now,
238	          completedAt: null,
239	        });
240	
241	        yield* repairAlarm();
242	      });
243	
244	    const updateScheduledRoundForPulse = (pulseId: PulseId, now: number) =>
245	      Effect.gen(function* () {
246	        const scheduled = yield* rounds.findScheduledRound(pulseId);
247	        if (scheduled === null) return;
248	
249	        const [dirState, pulseState] = yield* both;
250	        const pulse = pulseState.pulses.find((p) => p.id === pulseId);
251	        if (pulse === undefined) return;
252	        const team = dirState.teams.find((t) => t.id === scheduled.teamId);
253	        if (team === undefined) return;
254	
255	        const { memberTimeZones } = yield* activeMembersWithTimeZones(
256	          dirState,
257	          scheduled.teamId,
258	          team.timeZone,
259	        );
260	        const { plannedOpenDate, instants } = nextRoundSlot({
261	          now,
262	          weekday: pulse.settings.cadence.day,
263	          sendTime: pulse.settings.cadence.time,
264	          teamTimeZone: team.timeZone,
265	          memberTimeZones,
266	          answerWindowDays: pulse.settings.answerWindowDays,
267	          unavailableDates: yield* rounds.getUnavailableRoundDates(pulseId, scheduled.id),
268	        });
269	
270	        yield* rounds.updateScheduledRound(scheduled.id, {
271	          pulseName: pulse.settings.name,
272	          answerWindowDays: pulse.settings.answerWindowDays,
273	          reminders: pulse.settings.reminders,
274	          plannedOpenDate,
275	          plannedOpenAt: instants.openInstant,
276	          plannedCloseAt: instants.closeInstant,
277	          now,
278	        });
279	        yield* rounds.updateJobDueAt(scheduled.id, "open", instants.openInstant);
280	        yield* repairAlarm();
281	      });
282	
283	    const reviewEndsAtOf = (pulseState: PulseState, pulseId: PulseId, now: number) => {
284	      const pulse = pulseState.pulses.find((p) => p.id === pulseId);
285	      return now + (pulse?.settings.reviewWindowDays ?? 0) * 86_400_000;
286	    };
287	
288	    const firstRatingQuestionOf = (pulse: PulseRecord, pulseState: PulseState) => {
289	      const firstVersionId = pulse.questions[0];
290	      const firstVersion =
291	        firstVersionId !== undefined ? pulseState.versions.find((v) => v.id === firstVersionId) : undefined;
292	      return firstVersion && firstVersion.content.type._tag === "Rating"
293	        ? {
294	            text: firstVersion.content.text,
295	            lowLabel: firstVersion.content.type.lowLabel,
296	            highLabel: firstVersion.content.type.highLabel,
297	          }
298	        : null;
299	    };
300	
301	    const executeOpenJob = (jobId: JobId, roundId: RoundId, now: number) =>
302	      Effect.gen(function* () {
303	        const job = yield* rounds.getJob(jobId);
304	        if (job === null || job.status !== "pending") return;
305	
306	        const round = yield* rounds.getRound(roundId);
307	        if (round === null || round.status !== "scheduled") {
308	          yield* rounds.markJobCompleted(jobId, now);
309	          return;
310	        }
311	
312	        const existingInvitations = yield* rounds.getInvitations(roundId);
313	        if (existingInvitations.length > 0) {
314	          yield* rounds.markJobCompleted(jobId, now);
315	          return;
316	        }
317	
318	        const [dirState, pulseState] = yield* both;
319	        const pulse = pulseState.pulses.find((p) => p.id === round.pulseId);
320	        const team = dirState.teams.find((t) => t.id === round.teamId);
321	        if (pulse === undefined || team === undefined) {
322	          yield* rounds.cancelRound(roundId, now);
323	          yield* rounds.markJobCompleted(jobId, now);
324	          return;
325	        }
326	
327	        const { activeMembers, memberTimeZones } = yield* activeMembersWithTimeZones(
328	          dirState,
329	          round.teamId,
330	          team.timeZone,
331	        );
332	
333	        const instants = calculateRoundInstants(
334	          round.plannedOpenDate,
335	          pulse.settings.cadence.time,
336	          memberTimeZones,
337	          team.timeZone,
338	          round.answerWindowDays,
339	        );
340	
341	        const frozenMembers: ReadonlyArray<FrozenRoundMember> = activeMembers.map((m, idx) => {
342	          const tz = memberTimeZones[idx] ?? team.timeZone;
343	          const sendAt = instants.sends.find((s) => s.timeZone === tz)?.sendAt ?? instants.openInstant;
344	          return {
345	            roundId,
346	            personId: m.personId,
347	            timeZone: tz,
348	            sendAt,
349	          };
350	        });
351	
352	        yield* rounds.openRound(roundId, now, instants.closeInstant, pulse.questions, frozenMembers);
353	
354	        const ratingQuestion = firstRatingQuestionOf(pulse, pulseState);
355	        const eligibleActions = yield* actions.getEligibleActionsForRound(
356	          round.teamId,
357	          round.pulseId,
358	          round.plannedOpenAt,
359	        );
360	        const emailActions = eligibleActions.slice(0, 3).map((a) => a.title);
361	
362	        for (const m of frozenMembers) {
363	          const person = dirState.people.find((p) => p.id === m.personId);
364	          if (person === undefined || person.removedAt !== null) continue;
365	
366	          const invitation = { roundId, personId: m.personId, generation: 0 };
367	          const tokenHash = yield* tokenOf(invitation).pipe(
368	            Effect.flatMap((token) => Effect.promise(() => hashToken(token))),
369	          );
370	          const sendId = SendId.make(randomId());
371	
372	          yield* rounds.insertInvitations([
373	            {
374	              roundId,
375	              personId: m.personId,
376	              tokenHash,
377	              sendId,
378	              status: "pending",
379	              failedReason: null,
380	              resendCount: 0,
381	              createdAt: now,
382	              updatedAt: now,
383	            },
384	          ]);
385	
386	          const invitationEmail: TransactionalEmail = {
387	            _tag: "InvitationEmail",
388	            locale: emailLocaleOf(dirState, person.id),
389	            pulseName: pulse.settings.name,
390	            minimumGroupSize: dirState.minimumGroupSize,
391	            invitation,
392	            baseUrl: appOrigin,
393	            ratingQuestion,
394	            actions: emailActions,
395	            aiProcessing: dirState.aiProcessing,
396	          };
397	
398	          if (m.sendAt <= now) {
399	            yield* sends.create(sendId, person.email, invitationEmail);
400	          } else {
401	            yield* rounds.insertJob({
402	              id: JobId.make(randomId()),
403	              roundId,
404	              type: "send",
405	              dueAt: m.sendAt,
406	              status: "pending",
407	              payload: JSON.stringify({ personId: m.personId }),
408	              createdAt: now,
409	              completedAt: null,
410	            });
411	          }
412	
413	          const reminderInstants = calculateReminders(
414	            m.sendAt,
415	            round.answerWindowDays,
416	            pulse.settings.reminders,
417	            instants.closeInstant,
418	          );
419	          for (const remindAt of reminderInstants) {
420	            yield* rounds.insertJob({
421	              id: JobId.make(randomId()),
422	              roundId,
423	              type: "remind",
424	              dueAt: remindAt,
425	              status: "pending",
426	              payload: JSON.stringify({ personId: m.personId }),
427	              createdAt: now,
428	              completedAt: null,
429	            });
430	          }
431	        }
432	
433	        yield* rounds.insertJob({
434	          id: JobId.make(randomId()),
435	          roundId,
436	          type: "close",
437	          dueAt: instants.closeInstant,
438	          status: "pending",
439	          payload: null,
440	          createdAt: now,
441	          completedAt: null,
442	        });
443	
444	        yield* rounds.markJobCompleted(jobId, now);
445	
446	        yield* scheduleNextRound(round.pulseId, round.teamId, now);
447	      });
448	
449	    const InvitationJobPayload = Schema.Struct({
450	      personId: Schema.String,
451	      token: Schema.optionalKey(Schema.String),
452	    });
453	    const decodeInvitationJobPayload = Schema.decodeUnknownOption(InvitationJobPayload);
454	
455	    const ResultsReadyJobPayload = Schema.Struct({
456	      kind: Schema.Literal("resultsReady"),
457	      personId: Schema.String,
458	      roundId: Schema.String,
459	    });
460	    const decodeResultsReadyJobPayload = Schema.decodeUnknownOption(ResultsReadyJobPayload);
461	
462	    const parseJobPayload = (
463	      raw: string | null,
464	    ): { readonly personId: string; readonly token?: string } | null => {
465	      if (raw === null) return null;
466	      try {
467	        return Option.getOrNull(decodeInvitationJobPayload(JSON.parse(raw)));
468	      } catch {
469	        return null;
470	      }
471	    };
472	
473	    const parseSendPayload = (
474	      raw: string | null,
475	    ):
476	      | { readonly kind: "resultsReady"; readonly personId: string; readonly roundId: string }
477	      | { readonly personId: string; readonly token?: string }
478	      | null => {
479	      if (raw === null) return null;
480	      try {
481	        const parsed = JSON.parse(raw);
482	        const rr = Option.getOrNull(decodeResultsReadyJobPayload(parsed));
483	        if (rr !== null) return rr;
484	        return Option.getOrNull(decodeInvitationJobPayload(parsed));
485	      } catch {
486	        return null;
487	      }
488	    };
489	
490	    const executeSendJob = (jobId: JobId, roundId: RoundId, now: number) =>
491	      Effect.gen(function* () {
492	        const job = yield* rounds.getJob(jobId);
493	        if (job === null || job.status !== "pending") return;
494	
495	        const round = yield* rounds.getRound(roundId);
496	        if (round === null) {
497	          yield* rounds.markJobCompleted(jobId, now);
498	          return;
499	        }
500	
501	        const payload = parseSendPayload(job.payload);
502	        if (payload === null) {
503	          yield* rounds.markJobCompleted(jobId, now);
504	          return;
505	        }
506	
507	        if ("kind" in payload) {
508	          if (round.status !== "ready" && round.status !== "shared") {
509	            yield* rounds.markJobCompleted(jobId, now);
510	            return;
511	          }
512	
513	          const [dirState, pulseState] = yield* both;
514	          const pulse = pulseState.pulses.find((p) => p.id === round.pulseId);
515	          const team = dirState.teams.find((t) => t.id === round.teamId);
516	          const person = dirState.people.find((p) => p.id === payload.personId);
517	          if (pulse === undefined || person === undefined || person.removedAt !== null) {
518	            yield* rounds.markJobCompleted(jobId, now);
519	            return;
520	          }
521	
522	          const storedResult = yield* rounds.getRoundResult(roundId);
523	          const responseRatePercent = Math.round((storedResult?.responseRate ?? 0) * 100);
524	
525	          const resultsReadyEmail: TransactionalEmail = {
526	            _tag: "ResultsReadyEmail",
527	            locale: emailLocaleOf(dirState, person.id),
528	            pulseName: pulse.settings.name,
529	            teamName: team?.name ?? pulse.settings.name,
530	            resultsUrl: `${appOrigin}/teams/${round.teamId}/rounds/${roundId}`,
531	            responseRatePercent,
532	          };
533	
534	          const sendId = SendId.make(randomId());
535	          yield* sends.create(sendId, person.email, resultsReadyEmail);
536	          yield* rounds.markJobCompleted(jobId, now);
537	          return;
538	        }
539	
540	        if (round.status !== "open") {
541	          yield* rounds.markJobCompleted(jobId, now);
542	          return;
543	        }
544	
545	        const { personId } = payload;
546	        const [dirState, pulseState] = yield* both;
547	        const pulse = pulseState.pulses.find((p) => p.id === round.pulseId);
548	        const person = dirState.people.find((p) => p.id === personId);
549	        if (pulse === undefined || person === undefined || person.removedAt !== null) {
550	          yield* rounds.markJobCompleted(jobId, now);
551	          return;
552	        }
553	
554	        const inv = yield* rounds.getInvitation(roundId, PersonId.make(personId));
555	        if (inv === null || inv.status === "revoked") {
556	          yield* rounds.markJobCompleted(jobId, now);
557	          return;
558	        }
559	
560	        const ratingQuestion = firstRatingQuestionOf(pulse, pulseState);
561	        const eligibleActions = yield* actions.getEligibleActionsForRound(
562	          round.teamId,
563	          round.pulseId,
564	          round.plannedOpenAt,
565	        );
566	
567	        const common = {
568	          locale: emailLocaleOf(dirState, person.id),
569	          pulseName: pulse.settings.name,
570	          minimumGroupSize: dirState.minimumGroupSize,
571	          baseUrl: appOrigin,
572	          ratingQuestion,
573	          actions: eligibleActions.slice(0, 3).map((a) => a.title),
574	          aiProcessing: dirState.aiProcessing,
575	        };
576	        const invitationEmail: StoredEmail =
577	          payload.token === undefined
578	            ? {
579	                _tag: "InvitationEmail",
580	                ...common,
581	                invitation: { roundId, personId, generation: inv.resendCount },
582	              }
583	            : { _tag: "InvitationEmail", ...common, token: payload.token };
584	
585	        yield* sends.create(inv.sendId, person.email, invitationEmail);
586	        yield* rounds.markJobCompleted(jobId, now);
587	      });
588	
589	    const executeRemindJob = (jobId: JobId, roundId: RoundId, now: number) =>
590	      Effect.gen(function* () {
591	        const job = yield* rounds.getJob(jobId);
592	        if (job === null || job.status !== "pending") return;
593	
594	        const round = yield* rounds.getRound(roundId);
595	        if (round === null || round.status !== "open") {
596	          yield* rounds.markJobCompleted(jobId, now);
597	          return;
598	        }
599	
600	        if (now >= round.plannedCloseAt - 2 * 3600_000) {
601	          yield* rounds.markJobCompleted(jobId, now);
602	          return;
603	        }
604	
605	        const payload = parseJobPayload(job.payload);
606	        if (payload === null) {
607	          yield* rounds.markJobCompleted(jobId, now);
608	          return;
609	        }
610	
611	        const { personId } = payload;
612	        const pid = PersonId.make(personId);
613	
614	        const answered = yield* rounds.hasAnswered(roundId, pid);
615	        if (answered) {
616	          yield* rounds.markJobCompleted(jobId, now);
617	          return;
618	        }
619	
620	        const optedOut = yield* rounds.isOptedOut(round.pulseId, pid);
621	        if (optedOut) {
622	          yield* rounds.markJobCompleted(jobId, now);
623	          return;
624	        }
625	
626	        const [dirState, pulseState] = yield* both;
